pub use rf_d_circuit::{StepError,junction_charge};
#[path="../crates/rf-d-circuit/src/nominal_render.rs"]mod render;
#[path="../crates/rf-d-circuit/tests/support/mixer_chain_lab.rs"]mod lab;
use render::{RenderSession,WavSink,Phase,producer::{Producer,Pending,US,stream::{Frame,startup::*}}};
use std::{io::{Write,BufWriter},alloc::{GlobalAlloc,Layout,System},sync::atomic::{AtomicUsize,Ordering}};
struct Counter;static ALLOCS:AtomicUsize=AtomicUsize::new(0);
unsafe impl GlobalAlloc for Counter{unsafe fn alloc(&self,l:Layout)->*mut u8{ALLOCS.fetch_add(1,Ordering::Relaxed);System.alloc(l)}unsafe fn dealloc(&self,p:*mut u8,l:Layout){System.dealloc(p,l)}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{ALLOCS.fetch_add(1,Ordering::Relaxed);System.realloc(p,l,n)}}
#[global_allocator]static ALLOCATOR:Counter=Counter;
fn state(a:State,b:State){assert_eq!(a.optional,b.optional);for k in 0..118{assert_eq!(a.high[k].to_bits(),b.high[k].to_bits());assert_eq!(a.low[k].to_bits(),b.low[k].to_bits());}}
fn pair(a:&Pair,b:&Pair){for k in 0..2{state(a.delta[k],b.delta[k]);state(a.stages[k],b.stages[k]);}assert_eq!(a.residual_a.to_bits(),b.residual_a.to_bits());assert_eq!(a.correction_v.to_bits(),b.correction_v.to_bits());assert_eq!(a.iterations,b.iterations);}
fn accepted(a:&Accepted,b:&Accepted){pair(&a.coarse,&b.coarse);pair(&a.fine[0],&b.fine[0]);pair(&a.fine[1],&b.fine[1]);assert_eq!(a.h.to_bits(),b.h.to_bits());assert_eq!(a.error.to_bits(),b.error.to_bits());assert_eq!(a.attempts,b.attempts);}
fn pending(a:&Pending,b:&Pending){state(a.old,b.old);accepted(&a.accepted,&b.accepted);assert_eq!(a.start,b.start);assert_eq!(a.span,b.span);}
fn same(a:&Producer,b:&Producer){state(a.state(),b.state());assert_eq!(a.solved_ticks(),b.solved_ticks());assert_eq!(a.end_ticks(),b.end_ticks());assert_eq!(a.next_grid_ticks(),b.next_grid_ticks());assert_eq!(a.proposal_ticks(),b.proposal_ticks());assert_eq!(a.invocations(),b.invocations());assert_eq!(a.accepted_steps(),b.accepted_steps());assert!(a.output()==b.output());match(a.pending(),b.pending()){(Some(a),Some(b))=>pending(a,b),(None,None)=>(),_=>panic!("pending lost")}}
fn chain()->rf_d_circuit::chain_charge::Parameters{let(a,b,c)=lab::lab_parameters();rf_d_circuit::chain_charge::Parameters{circuit:a,conversion:b,headphone:c,boundary:lab::controlled_boundary(0,true),mixer:rf_d_circuit::mixer_on::OnMixer::new([false;5],[0.5;4]).unwrap()}}
fn read(path:&str)->Vec<f64>{std::fs::read(path).unwrap().chunks_exact(8).map(|b|f64::from_le_bytes(b.try_into().unwrap())).collect()}
fn values(frames:&[Frame],expected:&[f64],count:&mut usize){for f in frames{assert_eq!(f.source_index,*count as u64);assert_eq!(f.ready_input_index,8*f.source_index+384);assert_eq!(f.voltage_v.to_bits(),expected[*count].to_bits());*count+=1;}}
fn main(){let args:Vec<_>=std::env::args().collect();let expected=read(&args[1]);assert_eq!(expected.len(),433);let file=std::fs::OpenOptions::new().write(true).create_new(true).open(&args[2]).unwrap();let mut sink=WavSink::new(BufWriter::new(file),432).unwrap();let mut job=RenderSession::cold_start(chain(),9).unwrap();let mut w=Workspace::new();let(mut calls,mut count,mut heap,mut cancellations,mut zero_calls)=(0,0,0,0,0);let mut frames=[Frame::EMPTY;16];let mut last=job.progress();
    while job.phase()==Phase::Running{
        let quota=[0,7,127,1,31][calls%5];let cap=if cancellations==0{0}else{[0,1,3,0,16][calls%5]};let n=ALLOCS.load(Ordering::Relaxed);
        let r=job.pump(&mut w,quota,&mut frames[..cap],false);assert!(r.invocations<=quota);if quota==0{zero_calls+=1;assert_eq!(r.invocations,0);}let progress=job.progress();assert!(progress.solved_ticks>=last.solved_ticks&&progress.consumed_ticks>=last.consumed_ticks&&progress.consumed_ticks<=progress.solved_ticks&&progress.observed_frames>=last.observed_frames);last=progress;
        heap+=ALLOCS.load(Ordering::Relaxed)-n;assert!(!matches!(r.phase,Phase::Fault(_)|Phase::Cancelled));values(&frames[..r.written],&expected,&mut count);sink.write_frames(&frames[..r.written]).unwrap();
        if job.producer().pending().is_some()&&cancellations==0{
            assert_eq!(job.progress().solved_ticks,1000*US);let n=ALLOCS.load(Ordering::Relaxed);let saved=job.clone();let mut cancelled=saved.clone();let mut out=[Frame{source_index:99,ready_input_index:99,voltage_v:7.};1];let sentinel=out;let before=cancelled.progress();
            for cancel in[true,false,true]{let r=cancelled.pump(&mut w,4096,&mut out,cancel);assert_eq!(r.phase,Phase::Cancelled);assert_eq!(r.written,0);assert_eq!(r.invocations,0);assert_eq!(out,sentinel);assert_eq!(cancelled.progress(),before);same(cancelled.producer(),saved.producer());}
            let mut branch=saved;let mut fresh=Workspace::new();let mut other=out;let a=job.pump(&mut w,0,&mut out,false);let b=branch.pump(&mut fresh,0,&mut other,false);assert_eq!(a,b);assert_eq!(a.invocations,0);assert_eq!(a.written,1);assert_eq!(out,other);assert_eq!(job.progress(),branch.progress());same(job.producer(),branch.producer());heap+=ALLOCS.load(Ordering::Relaxed)-n;values(&out[..a.written],&expected,&mut count);sink.write_frames(&out[..a.written]).unwrap();cancellations+=1;last=job.progress();
        }calls+=1;assert!(calls<20000);
    }
    // Independent predecessor schedule: fixed admitted maximum 1 us.
    let mut control=render::producer::stream::startup::cold_start(chain()).unwrap().state;let base=Parameters::new(chain()).unwrap();let mut wc=Workspace::new();let mut cp=render::producer::stream::Pipeline::new(control).unwrap();let(mut t,mut grid,mut proposal,mut steps)=(0,125*US,US,0);let(mut max_r,mut max_c,mut max_e)=(0_f64,0_f64,0_f64);let mut minimum=1_f64;let tick=render::producer::stream::reference_readout::TICK_S;
    while t<10000*US{let event=if t<1000*US{1000*US}else{10000*US};let remain=event.min(grid)-t;let span=proposal.min(1_u64<<(63-remain.leading_zeros()));let mut p=base;p.time=t as f64*tick;let old=control;let q=voice::advance(&mut wc,p,&mut control,Controls{key:if t>=1000*US{10.}else{0.},short:false,optional:false},span as f64*tick).unwrap();let actual=(q.h/tick).round()as u64;cp.append(old,&q,t,actual,&mut[Frame::EMPTY;1]).unwrap();t+=actual;steps+=1;proposal=if q.error<0.05{(2*actual).min(US)}else{actual};if t==grid{grid+=125*US;}for p in [&q.coarse,&q.fine[0],&q.fine[1]]{max_r=max_r.max(p.residual_a);max_c=max_c.max(p.correction_v);}minimum=minimum.min(q.h);max_e=max_e.max(q.error);}
    state(job.producer().state(),control);assert!(job.producer().output()==&cp);assert_eq!(job.progress().invocations,steps);assert!(max_r<=1e-12&&max_c<=2e-9&&max_e<=1.);
    println!("CONTROL,{t},{steps},{},{},{minimum:.17e},{max_r:.17e},{max_c:.17e},{max_e:.17e}",cp.consumed(),cp.produced());
    sink.finish().unwrap();assert_eq!(job.phase(),Phase::Complete);let a=job.anchor().unwrap();assert_eq!(a.source_index,432);assert_eq!(a.ready_input_index,3840);assert_eq!(a.voltage_v.to_bits(),expected[432].to_bits());assert_eq!(count,432);assert_eq!(job.progress().observed_frames,433);assert_eq!(job.progress().invocations,steps);assert_eq!(job.producer().output().consumed(),3841);assert_eq!(heap,0);assert_eq!(cancellations,1);
    let n=ALLOCS.load(Ordering::Relaxed);let before=job.progress();for cancel in[true,false]{let mut out=[Frame::EMPTY;1];let r=job.pump(&mut w,4096,&mut out,cancel);assert_eq!(r.phase,Phase::Complete);assert_eq!(r.written,0);assert_eq!(r.invocations,0);assert_eq!(job.progress(),before);assert_eq!(out,[Frame::EMPTY;1]);}assert_eq!(ALLOCS.load(Ordering::Relaxed)-n,0);
    println!("PREFIX,{calls},{count},{heap},{cancellations},{zero_calls},{},{},{},{},{}",job.progress().solved_ticks,job.progress().invocations,job.progress().accepted_steps,job.progress().observed_frames,job.producer().output().consumed());println!("SIZES,{},{},{}",std::mem::size_of::<RenderSession>(),std::mem::size_of::<WavSink<std::io::Sink>>(),std::mem::size_of::<Workspace>());
}
